<?php
require_once dirname(__DIR__).'/app/helpers.php';require_auth();require_once dirname(__DIR__).'/app/Services/CardService.php';$svc=new CardService(Database::connection());$uid=(int)auth_user()['id'];$error=null;$success=null;$issued=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=$_POST['action']??'';if($action==='issue'){$issued=$svc->issue($uid,(int)$_POST['account_id'],$_POST['card_type']??'virtual',$_POST['network']??'demo_visa');$success=t('Card issued. Save the card details shown below; the full card number is not stored for later display.');}elseif($action==='status'){$svc->setStatus($uid,(int)$_POST['card_id'],$_POST['status']);$success=t('Card status updated.');}elseif($action==='pin'){$svc->setPin($uid,(int)$_POST['card_id'],trim($_POST['pin']));$success=t('Card PIN set.');}elseif($action==='limits'){$svc->setLimits($uid,(int)$_POST['card_id'],trim($_POST['daily_limit']),trim($_POST['per_transaction_limit']));$success=t('Card limits updated.');}}catch(Throwable $e){$error=$e->getMessage();}}$cards=$svc->list($uid);$stmt=Database::connection()->prepare('SELECT a.id,a.account_number,at.currency,a.available_balance FROM accounts a JOIN account_types at ON at.id=a.account_type_id WHERE a.user_id=? AND a.status="active" ORDER BY a.id');$stmt->execute([$uid]);$accounts=$stmt->fetchAll();$pageTitle=t('My Cards');$currentPage='cards';require __DIR__.'/partials/header.php';require __DIR__.'/partials/sidebar.php';?><div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><h2><?=e(t('My Cards'))?></h2><a href="<?=url('dashboard.php')?>"><?=e(t('Dashboard'))?></a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($issued):?><div class="alert alert-info"><b><?=e(t('Card details — save now:'))?></b><br><?=e(t('Card number'))?>: <code><?=e($issued['pan'])?></code><br><?=e(t('Expiry'))?>: <?=e(sprintf('%02d/%d',$issued['expiry_month'],$issued['expiry_year']))?><br><?=e(t('CVV'))?>: <code><?=e($issued['cvv'])?></code></div><?php endif;?><div class="card border-0 shadow-sm mb-4"><div class="card-body"><h5><?=e(t('Issue a new card'))?></h5><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="issue"><div class="col-md-4"><label class="form-label"><?=e(t('Account'))?></label><select name="account_id" class="form-select" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['account_number'])?> — <?=format_money($a['available_balance'],$a['currency'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label"><?=e(t('Card type'))?></label><select name="card_type" class="form-select"><option value="virtual"><?=e(t('Virtual'))?></option><option value="debit"><?=e(t('Debit'))?></option></select></div><div class="col-md-3"><label class="form-label"><?=e(t('Network'))?></label><select name="network" class="form-select"><option value="demo_visa"><?=e(t('Visa'))?></option><option value="demo_mastercard"><?=e(t('Mastercard'))?></option></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100"><?=e(t('Issue'))?></button></div></form></div></div><div class="row g-3"><?php foreach($cards as $c):?><div class="col-lg-6"><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between"><h5><?=e($c['network']==='demo_mastercard'?t('Mastercard'):t('Visa'))?></h5><span class="badge text-bg-<?=($c['status']==='active'?'success':'secondary')?>"><?=e(tx_label($c['status']))?></span></div><div class="fs-4">•••• •••• •••• <?=e($c['last4'])?></div><div class="small text-muted mb-3"><?=e(tx_label($c['card_type']))?> · <?=e(t('Expires'))?> <?=e(sprintf('%02d/%d',$c['expiry_month'],$c['expiry_year']))?> · <?=e(t('Account'))?> <?=e($c['account_number'])?></div><div class="d-flex gap-2 flex-wrap"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="card_id" value="<?=$c['id']?>"><input type="hidden" name="status" value="<?=$c['status']==='active'?'frozen':'active'?>"><button class="btn btn-sm btn-outline-secondary"><?=$c['status']==='active'?e(t('Freeze')):e(t('Unfreeze'))?></button></form><form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="action" value="pin"><input type="hidden" name="card_id" value="<?=$c['id']?>"><input name="pin" class="form-control form-control-sm" placeholder="<?=e(t('4-6 digit PIN'))?>" inputmode="numeric" required><button class="btn btn-sm btn-outline-primary"><?=e(t('Set PIN'))?></button></form></div><hr><form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="action" value="limits"><input type="hidden" name="card_id" value="<?=$c['id']?>"><div class="col"><input name="daily_limit" class="form-control form-control-sm" value="<?=$c['daily_limit']?>" placeholder="<?=e(t('Daily limit'))?>"></div><div class="col"><input name="per_transaction_limit" class="form-control form-control-sm" value="<?=$c['per_transaction_limit']?>" placeholder="<?=e(t('Per transaction'))?>"></div><div class="col-auto"><button class="btn btn-sm btn-outline-dark"><?=e(t('Save limits'))?></button></div></form></div></div></div><?php endforeach;?></div></div><?php require __DIR__.'/partials/footer.php';?>
